import argparse
import re
import subprocess
from pathlib import Path
from shutil import which
from textwrap import dedent


def gen_resources(input_dir: Path, output_file: Path):
    non_continue = re.compile(r"[^a-zA-Z0-9]")
    non_start = re.compile(r"[^a-zA-Z]")

    with open(output_file, "w") as file:
        file.write(dedent("""\
        // This file contains generated resources from the resources folder.
        // DO NOT EDIT THIS FILE!
        // Well you can, but dont expect your changes to persist >:)
        
        #pragma once
        
        """))

        file.write("namespace bpp {\n")

        def sanitize(name: str) -> str:
            name = non_continue.sub("_", name)
            if name and non_start.match(name[0]):
                name = "_" + name
            return name.lower()

        def walk(current: Path):
            path = [current]

            entries = list(current.iterdir())

            while len(entries) == 1 and entries[0].is_dir():
                path.append(entries[0])
                entries = list(entries[0].iterdir())

            namespace = "::".join(sanitize(entry.name) for entry in path)
            file.write(f"namespace {namespace} {{\n")

            print(f"{namespace}:")

            for entry in entries:
                if entry.is_dir():
                    walk(entry)
                else:
                    name = sanitize(entry.name)
                    path = entry.relative_to(input_dir.parent).as_posix()
                    file.write(f'constexpr const char *{name} = "{path}";\n')

                    print(f"{name} -> {path}")

            file.write(f"}}\n")

        walk(input_dir)

        file.write("}\n")

    # noinspection PyDeprecation
    clang_format = which("clang-format")
    if clang_format:
        subprocess.run([clang_format, "-i", output_file])


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Generate C++ resource header file from directory entries")
    parser.add_argument("-i", "--input", required=True, help="Input directory")
    parser.add_argument("-o", "--output", required=True, help="Output C++ header file")

    args = parser.parse_args()

    input_dir = Path(args.input)
    output_file = Path(args.output)

    print("Generating resource header file from directory")
    print(f"Input directory: {input_dir}")
    print(f"Output file: {output_file}")

    gen_resources(input_dir, output_file)
